src_resolver.prosrc:
DECLARE
  v_digits  TEXT;
  v_auth_id UUID;
  v_email   TEXT;
  v_hash    TEXT;
BEGIN
  -- Entradas obrigat├│rias (fail-closed, sem detalhe).
  IF p_cpf_cnpj IS NULL OR p_senha IS NULL
     OR btrim(p_cpf_cnpj) = '' OR p_senha = '' THEN
    RETURN NULL;
  END IF;

  -- Normaliza CPF/CNPJ (apenas d├¡gitos).
  v_digits := regexp_replace(btrim(p_cpf_cnpj), '[^0-9]', '', 'g');
  IF length(v_digits) < 11 THEN
    RETURN NULL;
  END IF;

  -- Identidade vinculada (no m├íximo uma).
  SELECT p.auth_user_id
    INTO v_auth_id
  FROM public.prestadores p
  WHERE p.auth_user_id IS NOT NULL
    AND regexp_replace(coalesce(p.cpf_cnpj, ''), '[^0-9]', '', 'g') = v_digits
  LIMIT 1;

  IF v_auth_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- auth.users SOMENTE pelo v├¡nculo objetivo auth_user_id.
  SELECT u.email, u.encrypted_password
    INTO v_email, v_hash
  FROM auth.users u
  WHERE u.id = v_auth_id
  LIMIT 1;

  IF v_email IS NULL OR v_hash IS NULL THEN
    RETURN NULL;
  END IF;

  -- Verifica a senha (bcrypt) SEM persistir/logar. Diverg├¬ncia ÔåÆ NULL.
  IF extensions.crypt(p_senha, v_hash) <> v_hash THEN
    RETURN NULL;
  END IF;

  RETURN v_email;
EXCEPTION
  WHEN OTHERS THEN
    -- Nunca vaza detalhe/exce├º├úo (indistingu├¡vel).
    RETURN NULL;
END;

src_criar.prosrc:
DECLARE
  v_auth_uid UUID;
  v_existing_id UUID;
  v_new_id UUID;
  v_nome TEXT;
  v_cpf TEXT;
  vTelefone TEXT;
  vEmail TEXT;
  vMeta JSONB;
BEGIN
  -- ========================================================================
  -- SEGURAN├çA: auth.uid() obrigat├│rio (fail-closed)
  -- ========================================================================
  v_auth_uid := auth.uid();
  IF v_auth_uid IS NULL THEN
    RAISE EXCEPTION 'Acesso negado: usu├írio n├úo autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  -- ========================================================================
  -- IDEMPOTENCIA: se j├í existe prestador para este auth_user, retorna
  -- ========================================================================
  SELECT id INTO v_existing_id
  FROM prestadores
  WHERE auth_user_id = v_auth_uid
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object('prestador_id', v_existing_id);
  END IF;

  -- ========================================================================
  -- SEGURAN├çA:Overrides de seguran├ºa ÔÇö ignora valores enviados pelo cliente
  -- ========================================================================
  v_nome  := trim(coalesce(p_nome_completo, ''));
  v_cpf   := CASE WHEN trim(coalesce(p_cpf_cnpj, '')) = '' THEN NULL
                  ELSE trim(p_cpf_cnpj) END;
  vTelefone := CASE WHEN trim(coalesce(p_telefone, '')) = '' THEN NULL
                    ELSE trim(p_telefone) END;
  vEmail    := CASE WHEN trim(coalesce(p_email, '')) = '' THEN NULL
                    ELSE trim(p_email) END;
  vMeta     := coalesce(p_metadata, '{}'::jsonb);

  -- Valida├º├úo: nome ├® obrigat├│rio
  IF v_nome = '' THEN
    RAISE EXCEPTION 'Nome completo ├® obrigat├│rio'
      USING ERRCODE = 'P0002';
  END IF;

  -- ========================================================================
  -- INSERT em prestadores
  -- ========================================================================
  INSERT INTO prestadores (
    nome_completo,
    cpf_cnpj,
    data_nascimento,
    telefone,
    email,
    auth_user_id,
    status,
    liberado_app,
    origem,
    origem_cadastro,
    metadata,
    created_at,
    updated_at
  ) VALUES (
    v_nome,
    v_cpf,
    CASE WHEN p_data_nascimento IS NOT NULL AND trim(p_data_nascimento) != ''
         THEN p_data_nascimento::date
         ELSE NULL END,
    vTelefone,
    vEmail,
    v_auth_uid,           -- anti-spoof: sempre auth.uid()
    'em_analise',         -- fixo: nunca liberado
    false,                -- fixo: nunca liberado
    coalesce(p_origem, 'app_prestador'),
    'app_motorista',      -- detectado pelo bridge enterpriseKanbanService
    vMeta,
    now(),
    now()
  )
  RETURNING id INTO v_new_id;

  -- ========================================================================
  -- RETORNO: formato { prestador_id: UUID }
  -- ========================================================================
  RETURN jsonb_build_object('prestador_id', v_new_id);
END;
